begin;

create table if not exists public.calendar_closures (
  id bigint generated by default as identity primary key,
  title text not null check (length(trim(title)) between 3 and 160),
  start_date date not null,
  end_date date not null,
  department_id bigint references public.academic_departments(id) on delete restrict,
  source_kind text not null check (source_kind in ('official_holiday', 'school_announcement')),
  source_url text,
  source_key text unique,
  is_active boolean not null default true,
  confirmed_by uuid references public.profiles(user_id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (end_date >= start_date),
  check (end_date <= start_date + 30)
);

create index if not exists calendar_closures_active_dates_idx
  on public.calendar_closures(start_date, end_date, department_id)
  where is_active = true;

alter table public.calendar_closures enable row level security;
revoke all on public.calendar_closures from anon, authenticated;

on conflict (source_key) do nothing;

commit;
